#!/usr/bin/env python3
"""Normalize the "status" field of a JSON file in place.

Reads the file, strips and lowercases the top-level "status" string value,
and writes the result back to the same path. Only the normalized value is
rewritten; all other formatting (indentation, spacing, non-ASCII literals,
trailing newline) is preserved verbatim.
"""
import argparse
import json
import sys
from pathlib import Path

FIELD = "status"


def normalize_value(value):
    if isinstance(value, str):
        return value.strip().lower()
    return value


def _value_span(text, field):
    """Return the (start, end) slice of the top-level `field` value in `text`."""
    decoder = json.JSONDecoder()
    i = text.index("{") + 1
    while True:
        while text[i] in " \t\n\r":
            i += 1
        if text[i] == "}":
            return None
        key, j = decoder.raw_decode(text, i)
        while text[j] in " \t\n\r":
            j += 1
        j += 1  # ':'
        while text[j] in " \t\n\r":
            j += 1
        value, end = decoder.raw_decode(text, j)
        if key == field:
            return (j, end)
        i = end
        while text[i] in " \t\n\r":
            i += 1
        if text[i] == ",":
            i += 1
            continue
        return None


def normalize_text(text):
    data = json.loads(text)
    if not isinstance(data, dict) or not isinstance(data.get(FIELD), str):
        return text, False
    new_literal = json.dumps(normalize_value(data[FIELD]), ensure_ascii=False)
    span = _value_span(text, FIELD)
    if span is None:
        return text, False
    start, end = span
    if text[start:end] == new_literal:
        return text, False
    return text[:start] + new_literal + text[end:], True


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("file", type=Path, help="JSON file to normalize in place")
    args = parser.parse_args(argv)

    new_text, changed = normalize_text(args.file.read_text(encoding="utf-8"))
    if changed:
        args.file.write_text(new_text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
